// services/gemini.ts
import { GoogleGenerativeAI } from '@google/generative-ai';
import { getMimeTypeFromBase64 } from '../utils/mimeTypeUtils';

const API_KEY = process.env.GOOGLE_API_KEY;

if (!API_KEY) {
  throw new Error('GOOGLE_API_KEY is not defined in the environment variables.');
}

const genAI = new GoogleGenerativeAI(API_KEY);

interface EditImageRequest {
  base64Image: string;
  prompt: string;
}

interface ImagePart {
  mimeType: string;
  data: string;
}

const imageModelName = 'gemini-2.5-flash-image';

export async function editImage(request: EditImageRequest): Promise<string | null> {
  try {
    const model = genAI.getGenerativeModel({ model: imageModelName });
    const imageMimeType = getMimeTypeFromBase64(request.base64Image) || 'image/png';

    const promptWithImage = {
      role: 'user',
      parts: [
        {
          inlineData: {
            mimeType: imageMimeType,
            data: request.base64Image,
          },
        },
        { text: request.prompt },
      ],
    };

    const result = await model.generateContentStream(promptWithImage);
    let response = null;

    for await (const chunk of result.stream) {
      const { text, candidates } = chunk.response;
      response = candidates?.[0]?.content?.parts;
    }

    if (!response) {
      return null;
    }

    let imagePart: ImagePart | undefined;
    for (const part of response) {
      if (part.mimeType && part.data) {
        imagePart = { mimeType: part.mimeType, data: part.data };
        break;
      }
    }

    if (!imagePart) {
      return null;
    }

    return imagePart.data;

  } catch (error) {
    console.error('Error during image editing:', error);
    return null;
  }
}

